package com.bank.diag;

public class DnsStep implements DiagnosticStep {
    private final String resolvedIp;              // null = NXDOMAIN
    private final String expectedLbIp;

    public DnsStep(String resolvedIp, String expectedLbIp) {
        this.resolvedIp = resolvedIp;
        this.expectedLbIp = expectedLbIp;
    }

    @Override
    public DiagnosticResult check(String accountId) {
        if (resolvedIp == null) {
            return new DiagnosticResult(hopName(), false,
                "api.nationalbank.in did not resolve (NXDOMAIN)");
        }
        if (!resolvedIp.equals(expectedLbIp)) {
            return new DiagnosticResult(hopName(), false,
                "DNS points to stale IP " + resolvedIp + ", expected " + expectedLbIp);
        }
        return new DiagnosticResult(hopName(), true, "resolves to " + resolvedIp);
    }

    @Override public String hopName() { return "DNS"; }
}
