package com.bank.diag;

public class IngressStep implements DiagnosticStep {
    private final int healthyTargets;
    private final String backendService;
    private final boolean backendExists;

    public IngressStep(int healthyTargets, String backendService, boolean backendExists) {
        this.healthyTargets = healthyTargets;
        this.backendService = backendService;
        this.backendExists = backendExists;
    }

    @Override
    public DiagnosticResult check(String accountId) {
        if (healthyTargets == 0) {
            return new DiagnosticResult(hopName(), false,
                "ALB target group has 0 healthy targets");
        }
        if (!backendExists) {
            return new DiagnosticResult(hopName(), false,
                "Ingress routes to missing Service '" + backendService + "'");
        }
        return new DiagnosticResult(hopName(), true,
            healthyTargets + " healthy targets, backend=" + backendService);
    }

    @Override public String hopName() { return "LoadBalancer/Ingress"; }
}
