        this.totalPods = totalPods;
        this.podPhase = podPhase;
    }

    @Override
    public DiagnosticResult check(String accountId) {
        if (readyEndpoints == 0) {
            return new DiagnosticResult(hopName(), false,
                "Service has 0 ready endpoints; " + totalPods
                    + " pods in phase " + podPhase + " (readiness probe failing)");
        }
        return new DiagnosticResult(hopName(), true,
            readyEndpoints + "/" + totalPods + " pods Ready");
    }

    @Override public String hopName() { return "Service/PodReadiness"; }
