package com.bank.diag;

public class AuthStep implements DiagnosticStep {
    private final boolean authServiceUp;
    private final boolean signingKeyValid;

    public AuthStep(boolean authServiceUp, boolean signingKeyValid) {
        this.authServiceUp = authServiceUp;
        this.signingKeyValid = signingKeyValid;
    }

    @Override
    public DiagnosticResult check(String accountId) {
        if (!authServiceUp) {
            return new DiagnosticResult(hopName(), false,
                "auth-service returning 500 (DB pool exhausted) for " + accountId);
        }
        if (!signingKeyValid) {
            return new DiagnosticResult(hopName(), false,
                "JWT signature invalid: verifier has stale public key after rotation");
        }
        return new DiagnosticResult(hopName(), true, "token issued and verified for " + accountId);
    }

    @Override public String hopName() { return "AuthService"; }
}
