package com.bank.diag;

import java.util.List;
import java.util.logging.Logger;

public class AccessDiagnosticEngine {
    private static final Logger log = Logger.getLogger(AccessDiagnosticEngine.class.getName());
    private final List<DiagnosticStep> steps;

    public AccessDiagnosticEngine(List<DiagnosticStep> steps) {
        this.steps = steps;
    }

    // Runs hops in order, stops at the FIRST failing hop (that is the culprit).
    public DiagnosticResult diagnose(String accountId) {
        log.info(() -> "Starting end-to-end access diagnosis for " + accountId);
        for (DiagnosticStep step : steps) {
            DiagnosticResult r = step.check(accountId);
            if (r.isHealthy()) {
                log.info(() -> "  [OK]   " + r.getHop() + ": " + r.getReason());
            } else {
                log.severe(() -> "  [FAIL] " + r.getHop() + ": " + r.getReason());
                log.severe(() -> "ROOT CAUSE at hop '" + r.getHop()
                    + "'. Fix this before checking later hops.");
                return r;
            }
        }
        log.info("All hops healthy — issue is client-side (browser cache / local network).");
        return new DiagnosticResult("ALL", true, "every hop healthy");
    }
}
