package com.bank.diag;

import java.util.List;
import java.util.logging.*;

public class AccessDebugDemo {
    private static final Logger log = Logger.getLogger(AccessDebugDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Scenario: DNS ok, ingress ok, but the banking Service has 0 ready endpoints
        // because the Pod's readiness probe fails (DB unreachable). Rajesh cannot log in.
        List<DiagnosticStep> steps = List.of(
            new DnsStep("10.0.5.20", "10.0.5.20"),
            new IngressStep(2, "banking-service", true),
            new ServiceReadinessStep(0, 3, "Running (NotReady)"),
            new AuthStep(true, true)
        );

        AccessDiagnosticEngine engine = new AccessDiagnosticEngine(steps);
        DiagnosticResult verdict = engine.diagnose("SAV2001");
        log.info(() -> "VERDICT: broken hop = " + verdict.getHop()
            + " | healthy=" + verdict.isHealthy());
    }
}
